script:
const op = context.pathParams.operation;
const body = JSON.parse(context.body || '{}');
const a = body.a || 0;
const b = body.b || 0;
let result;
switch (op) {
  case 'add': result = a + b; break;
  case 'sub': result = a - b; break;
  case 'mul': result = a * b; break;
  case 'div': result = b !== 0 ? a / b : 'Division by zero'; break;
  default: return { status: 400, body: { error: 'Unknown operation' } };
}
return {
  status: 200,
  headers: { 'x-computed-by': 'script-engine' },
  body: { operation: op, result: result }
};
